tinymce.PluginManager.add('texteditblock', function(editor, url) {

    editor.ui.registry.addButton('dynamictextblock', {
         text: 'Textblock',
          icon: 'table',
          image: tinymce.baseURL + '/plugins/texteditblock/textblock.svg',
          id: 'texteditblock',
          class: 'texteditblock',
          tooltip:'Textblock hinzufügen',
          stateSelector:"img .texteditblock",
          onAction: ShowTextBlockSetting
    });
});